 }
}

export const LogLevelToCode = (level: string) => {
 switch (level.toLowerCase()) {
 case 'info':
 case 'information':
 case 'low':
 return 'blue'
 case 'debug':
 return 'gray'
 case 'finished':
 case 'success':
 return 'green'
 case 'fatal':
 case 'error':
 case 'panic':
 case 'err':
 case 'high':
 case 'critical':
 return 'red'
 case 'warning':
 case 'warn':
 case 'middle':
 case 'medium':
 return 'orange'
 default:
 return 'blue'
 }
}

