// 触发时机：每个新的 schema+host 仅触发一次（由 yakit 引擎去重）
// 工作流程：从响应 header 取 Server/X-Powered-By；从 body 用关键字命中常见技术栈
fingerprintRecords = {}
TECH_KEYWORDS = [["WordPress", "wp-content"],
 ["jQuery", "jQuery"],
 ["Vue", "Vue.config"],
 ["React", "__REACT_DEVTOOLS_GLOBAL_HOOK__"],
 ["Bootstrap", "bootstrap.min.css"],
