}

/** 最新漏洞与风险信息 */
interface LatestRiskInfo {
 Title: string
 Id: number
 CreatedAt: number
 UpdatedAt: number
 Verbose: string
 TitleVerbose: string
 IsRead: boolean
}

interface RisksProps {
 Data: LatestRiskInfo[]
 Total: number
 NewRiskTotal: number
 /**全部未读 */
 Unread: number
}

/** 漏洞与风险等级对应关系 */
const RiskType: { [key: string]: string } = {
 信息: 'info',
 低危: 'low',
 中危: 'middle',
 高危: 'high',
 严重: 'critical',
}
const UIOpRisk: React.FC<UIOpRiskProp> = React.memo((props) => {
 const { isEngineLink } = props

 const [show, setShow] = useState<boolean>(false)

 /** 查询最新漏洞与风险信息节点 */
 const fetchNode = useRef<number>(0)
 const [risks, setRisks] = useState<RisksProps>({
 Data: [],
 Total: 0,
 NewRiskTotal: 0,
 Unread: 0,
 })

 /** 定时器 */
 const timeRef = useRef<(() => void) | null>(null)
 /** 风险详情弹窗（保证同时只存在一个） */
 const riskDetailModalRef = useRef<{ destroy: () => void } | null>(null)
 /** 打开详情中，防止同一次/连续点击叠多个弹窗 */
 const isOpeningDetailRef = useRef(false)

 /** 查询最新的风险数据 */
 const update = useMemoizedFn(() => {
 yakitRisk.fetchLatestInfo({ AfterId: fetchNode.current }).then((res: RisksProps) => {
 if (JSON.stringify(risks.Data) === JSON.stringify(res.Data) &&
 risks.NewRiskTotal === res.NewRiskTotal &&
 risks.Total === res.Total) {
 return
 }

 const risksOjb: RisksProps = {
 Total: res.Total,
 NewRiskTotal: res.NewRiskTotal,
 Unread: res.Unread,
 Data: [...res.Data],
 }
 setRisks({...risksOjb })
 }).catch(() => {})
 })

 /** 获取最新的漏洞与风险信息(5秒一次) */
 useEffect(() => {
 let cancelled = false
 const clearPoll = () => {
 timeRef.current?.()
 timeRef.current = null
 }
 if (isEngineLink) {
 clearPoll()
 yakitRisk.queryRisks({
 Pagination: { Limit: 1, Page: 1, Order: 'desc', OrderBy: 'id' },
 }).then((res: QueryGeneralResponse<Risk>) => {
 const { Data } = res
 fetchNode.current = Data.length === 0? 0: Data[0].Id
 }).catch((e) => {}).finally(() => {
 if (cancelled) return
 update()
 emiter.on('onRefreshQueryNewRisk', update)
 // 以下为兼容以前的引擎 PS:以前的引擎依然为轮询
 if (!serverPushStatus) {
 timeRef.current = startIdleVisibleInterval(() => {
 if (serverPushStatus) {
 clearPoll()
 return
 }
 update()
 }, 5000)
 }
 })
 emiter.on('onRefRisksRead', onRefRisksRead)
 return () => {
 cancelled = true
 clearPoll()
 emiter.off('onRefreshQueryNewRisk', update)
 emiter.off('onRefRisksRead', onRefRisksRead)
 }
 } else {
 clearPoll()
 fetchNode.current = 0
 setRisks({ Data: [], Total: 0, NewRiskTotal: 0, Unread: 0 })
 }
 }, [isEngineLink])

 const onRefRisksRead = useMemoizedFn((res) => {
 try {
 const value = JSONParseLog(res, { page: 'FuncDomain', fun: 'onRefRisksRead' })
 if (value.isAllRead) {
 // 全部已读
 setRisks({...risks,
 Unread: 0,
 NewRiskTotal: 0,
 Data: risks.Data.map((item) => ({...item, IsRead: true })),
 })
 } else if (value.Id) {
 // 单条已读
 const newRiskTotal = risks.NewRiskTotal - 1
 const newUnread = risks.Unread - 1
 setRisks({...risks,
 Unread: newUnread > 0? newUnread: 0,
 NewRiskTotal: newRiskTotal > 0? newRiskTotal: 0,
 Data: risks.Data.map((item) => {
 if (item.Id === value.Id) item.IsRead = true
 return item
 }),
 })
 }
 } catch (error) {}
 })

 /** 单条点击阅读 */
 const singleRead = useMemoizedFn((info: LatestRiskInfo) => {
 if (isOpeningDetailRef.current) return
 isOpeningDetailRef.current = true
 setShow(false)

 yakitRisk.setInfoRead({ AfterId: fetchNode.current, Ids: [info.Id] }).then(() => {
 const newUnread = risks.Unread - 1 > 0? risks.Unread - 1: 0
 const newRiskTotal = risks.NewRiskTotal - 1 > 0? risks.NewRiskTotal - 1: 0
 setRisks({...risks,
 NewRiskTotal: info.IsRead? risks.NewRiskTotal: newRiskTotal,
 Unread: info.IsRead? risks.Unread: newUnread,
 Data: risks.Data.map((item) => {
 if (item.Id === info.Id && item.Title === info.Title) item.IsRead = true
 return item
 }),
 })
 }).catch(() => {})
 yakitRisk.query({ Id: info.Id }).then((res: Risk) => {
 if (!res) return
 riskDetailModalRef.current?.destroy()
 const m = showYakitModal({
 width: '80%',
 title: '详情',
 content: (<div style={{ overflow: 'auto', maxHeight: '70vh' }}>
 <React.Suspense fallback={null}>
 {isShowCodeScanDetail(res)? (<YakitCodeScanRiskDetails info={res} />): (<YakitRiskDetails info={res} boxStyle={{ height: 400 }} />)}
 </React.Suspense>
 </div>),
 onOk: () => {
 m.destroy()
 },
 modalAfterClose: () => {
 if (riskDetailModalRef.current === m) {
 riskDetailModalRef.current = null
 }
 },
 })
 riskDetailModalRef.current = m
 }).catch(() => {}).finally(() => {
 isOpeningDetailRef.current = false
 })
 })
 /** 全部已读 */
 const allRead = useMemoizedFn(() => {
 yakitRisk.setInfoRead({ Ids: [] }).then(() => {
 setRisks({...risks,
 Unread: 0,
 NewRiskTotal: 0,
 Data: risks.Data.map((item) => {
 item.IsRead = true
 return item
 }),
 })
 emiter.emit('onRefRiskList')
 }).catch(() => {})
 })
