const RunnerTabPane: React.FC<RunnerTabPaneProps> = memo((props) => {
 const { tabsId } = props
 const { t, i18nRefresh } = useI18nNamespaces(['yakRunner'])
 const { areaInfo, activeFile } = useStore()
 const { setAreaInfo, setActiveFile } = useDispatcher()
 const [editorInfo, setEditorInfo] = useState<FileDetailInfo>()
 // 编辑器实例
 const [reqEditor, setReqEditor] = useState<IMonacoEditor>()
 // 是否允许展示二进制
 const [allowBinary, setAllowBinary] = useState<boolean>(false)
 const isDestroy = useRef<boolean>(false)

 const nowPathRef = useRef<string>()
 useEffect(() => {
 areaInfo.forEach((item) => {
 item.elements.forEach((itemIn) => {
 if (itemIn.id === tabsId) {
 itemIn.files.forEach((file) => {
 // 仅初次进入 或(切换/更新高亮显示区域/code变化)时更新详情
 if (file.isActive &&
 (!editorInfo ||
 (editorInfo && editorInfo.path!== file.path) ||
 (editorInfo && JSON.stringify(editorInfo.highLightRange)!== JSON.stringify(file.highLightRange)) ||
 // code如为缓存打开时则不存在 需特殊处理
 (typeof editorInfo.code!== 'string' && typeof file.code === 'string'))) {
 // 更新编辑器展示项
 nowPathRef.current = file.path
 setEditorInfo(file)
 setAllowBinary(false)
 }
 })
 }
 })
 })
 }, [areaInfo])

 // 光标位置信息
 const positionRef = useRef<CursorPosition>()
 const selectionRef = useRef<Selection>()

 // 自动保存
 const autoSaveCurrentFile = useDebounceFn((newEditorInfo: FileDetailInfo) => {
 const { path, code } = newEditorInfo
 code && grpcFetchSaveFile(path, code)
 },
 {
 wait: 500,
 },)

 // 优化性能 减少卡顿
 const updateAreaFun = useDebounceFn((content: string) => {
 if (editorInfo?.path) {
 const newAreaInfo = updateAreaFileInfo(areaInfo, { code: content }, editorInfo.path)
 // console.log("更新编辑器文件内容", newAreaInfo)
 setAreaInfo && setAreaInfo(newAreaInfo)
 }
 },
 {
 wait: 200,
 },).run

 // 更新编辑器文件内容(activeFile-code字段在光标位置改变时就已更新，为减少渲染，则不更新)
 const updateAreaInputInfo = useMemoizedFn((content: string) => {
 if (editorInfo) {
 const newEditorInfo = {...editorInfo, code: content }
 // 未保存文件不用自动保存 审计树文件不用自动保存
 if (!editorInfo?.isUnSave) {
 autoSaveCurrentFile.run(newEditorInfo)
 }
 setEditorInfo(newEditorInfo)
 }
 if (content!== editorInfo?.code) {
 updateAreaFun(content)
 }
 })

 // 更新当前底部展示信息
 const updateBottomEditorDetails = useDebounceFn(async () => {
 if (!editorInfo) return
 try {
 let newActiveFile = editorInfo
 // 注入语法检查结果
 newActiveFile = await getDefaultActiveFile(newActiveFile)
 // 如若文件检查结果出来时 文件已被切走 则不再更新
 if (newActiveFile.path!== nowPathRef.current || isDestroy.current) return
 // 更新位置信息
 if (positionRef.current) {
 // 此处还需要将位置信息记录至areaInfo用于下次打开时直接定位光标
 newActiveFile = {...newActiveFile, position: positionRef.current }
 }
 if (selectionRef.current) {
 // 此处还需要将位置信息记录至areaInfo用于下次打开时直接定位光标
 newActiveFile = {...newActiveFile, selections: selectionRef.current }
 }
 setActiveFile && setActiveFile(newActiveFile)
 const newAreaInfo = updateAreaFileInfo(areaInfo, newActiveFile, newActiveFile.path)
 // console.log("更新当前底部展示信息", newActiveFile, newAreaInfo)
 setAreaInfo && setAreaInfo(newAreaInfo)
 } catch (error) {}
 },
 {
 wait: 800,
 },).run

 // 聚焦时校验是否更新活跃文件
 const onSetActiveFileByFocus = useMemoizedFn(() => {
 if (activeFile?.path!== editorInfo?.path) {
 updateBottomEditorDetails()
 }
 })

 useEffect(() => {
 if (!reqEditor) {
 return
 }
 let isFocus = false
 // 监听光标点击位置
 const cursorPosition = reqEditor.onDidChangeCursorPosition((e) => {
 if (!isFocus) return
 const { position } = e
 // console.log("当前光标位置：", position)
 positionRef.current = position
 updateBottomEditorDetails()
 })
 // 监听光标选中位置
 const cursorSelection = reqEditor.onDidChangeCursorSelection((e) => {
 if (!isFocus) return
 const selection = e.selection
 const { startLineNumber, startColumn, endLineNumber, endColumn } = selection
 // console.log("当前光标选中位置", startLineNumber, startColumn, endLineNumber, endColumn)
 selectionRef.current = { startLineNumber, startColumn, endLineNumber, endColumn }
 // 选中时也调用了onDidChangeCursorPosition考虑优化掉重复调用
 // updateBottomEditorDetails()
 })
 // 监听编辑器是否聚焦
 const focusEditor = reqEditor.onDidFocusEditorWidget(() => {
 isFocus = true
 // console.log("聚焦", reqEditor.getPosition())
 // 此处获取光标位置的原因是由于点击空白区域焦点获取时 onDidChangeCursorPosition 无法监听
 if (reqEditor.getPosition()) {
 const focusLineNumber = reqEditor.getPosition()?.lineNumber
 const focusColumn = reqEditor.getPosition()?.column
 if (focusLineNumber && focusColumn) {
 positionRef.current = {
 lineNumber: focusLineNumber,
 column: focusColumn,
 }
 }
 }
 // 聚焦时更新目前活跃的文件展示
 onSetActiveFileByFocus()
 })
 // 监听编辑器是否失焦
 const blurEditor = reqEditor.onDidBlurEditorWidget(() => {
 isFocus = false
 // console.log("失焦")
 })

 return () => {
 // 在组件销毁时移除事件监听器
 cursorPosition.dispose()
 cursorSelection.dispose()
 focusEditor.dispose()
 blurEditor.dispose()
 isDestroy.current = true
 }
 }, [reqEditor])

 // 更新光标位置
 const updatePosition = useMemoizedFn(() => {
 // console.log("更新光标位置", editorInfo)
 if (reqEditor && editorInfo) {
 // 如若没有记录 默认1行1列
 // 性能优化设想: (核心抽离: position与selections的读取与更改)
 // 此处position与selections读取与更改不在editorInfo中进行
 // 选择使用map进行缓存以便于切换文件时恢复其焦点
 // 且使用单独state进行右下角更新而不影响editorInfo的更新从而不引起全局渲染
 const { position = { lineNumber: 1, column: 1 }, selections } = editorInfo
 const { lineNumber, column } = position
 if (lineNumber && column) {
 reqEditor.setPosition({ lineNumber, column })
 reqEditor.focus()
 }
 // 记录以前缓存的值用于刷新
 if (position) {
 positionRef.current = position
 }
 if (selections) {
 selectionRef.current = selections
 }
 }
 updateBottomEditorDetails()
 })

 // 此处ref存在意义为清除ctrl + z缓存 同时更新光标位置
 useUpdateEffect(() => {
 if (reqEditor && editorInfo?.code) {
 reqEditor.setValue(editorInfo.code)
 updatePosition()
 }
 }, [editorInfo?.path])

 // 选中光标位置
 const onJumpEditorDetailFun = useMemoizedFn((data) => {
 try {
 const obj: JumpToEditorProps = JSON.parse(data)
 const { path, isSelect = true, selections } = obj
 if (reqEditor && editorInfo?.path === path) {
 if (isSelect) {
 reqEditor.setSelection(selections)
 }
 reqEditor.revealLineInCenter(selections.startLineNumber)
 }
 } catch (error) {}
 })

 useEffect(() => {
 emiter.on('onAiCodeAuditJumpEditorDetail', onJumpEditorDetailFun)
 return () => {
 emiter.off('onAiCodeAuditJumpEditorDetail', onJumpEditorDetailFun)
 }
 }, [])

 // 打开二进制文件
 const onOpenBinary = useMemoizedFn(() => {
 if (!editorInfo) return
 setAllowBinary(true)
 const newAreaInfo = updateAreaFileInfo(areaInfo, {...editorInfo, isPlainText: true }, editorInfo.path)
 setAreaInfo && setAreaInfo(newAreaInfo)
 })

 useEffect(() => {
 if (editorInfo && typeof editorInfo?.code!== 'string') {
 // 如果没有code字段则说明是缓存打开 需加载其内容
 const { path, name, parent } = editorInfo
 const OpenFileByPathParams: OpenFileByPathProps = {
 params: {
 path,
 name,
 parent,
 },
 }
 emiter.emit('onAiCodeAuditGetCodeByPathCache', JSON.stringify(OpenFileByPathParams))
 }
 }, [editorInfo])

 const setReqEditorFun = useMemoizedFn((editor: IMonacoEditor) => {
 setReqEditor(editor)
 })

 const setYakitEditorValue = useCallback((content: string) => {
 if (typeof editorInfo?.code!== 'string') return
 updateAreaInputInfo(content)
 },
 [editorInfo?.code],)

 const onSendAIAction = useMemoizedFn((editor: IMonacoEditor) => {
 const content = fetchCursorContent(editor, true)
 const range = fetchSelectionRange(editor, true)
 const name = editorInfo?.name
 if (!name) return

 emiter.emit('onAiCodeAuditSendCodeBlock',
 JSON.stringify({
 type: 'codeBlockTag',
 params: {
 content,
 range: range? {
 startLineNumber: range.startLineNumber,
 startColumn: range.startColumn,
 endLineNumber: range.endLineNumber,
 endColumn: range.endColumn,
 }: null,
 name,
 language: editorInfo.language || '',
 path: editorInfo.path,
 // irify 由于在启动对话已给了根目录路径 此处无需另外给予
 rootPath: '',
 },
 }),)
 })

 const onSendAIActionRef = useRef(onSendAIAction)
 onSendAIActionRef.current = onSendAIAction

 const [selectionMenuVisible, setSelectionMenuVisible] = useState(false)
 const [selectionMenuPos, setSelectionMenuPos] = useState({ top: 0, left: 0 })
 const selectionMenuVisibleRef = useRef(false)

 const closeSelectionMenu = useMemoizedFn(() => {
 selectionMenuVisibleRef.current = false
 setSelectionMenuVisible(false)
 })

 const updateSelectionMenuPosition = useMemoizedFn((editor: IMonacoEditor) => {
 const selection = editor.getSelection()
 if (!selection) {
 closeSelectionMenu()
 return
 }
 const selectedText = editor.getModel()?.getValueInRange(selection) || ''
 if (!selectedText) {
 closeSelectionMenu()
 return
 }
 const anchorLine =
 selection.endLineNumber >= selection.startLineNumber? selection.endLineNumber: selection.startLineNumber
 const anchorColumn =
 selection.endLineNumber >= selection.startLineNumber? selection.endColumn: selection.startColumn
 const pos = editor.getScrolledVisiblePosition({ lineNumber: anchorLine, column: anchorColumn })
 if (!pos) {
 closeSelectionMenu()
 return
 }
 selectionMenuVisibleRef.current = true
 setSelectionMenuPos({ top: pos.top + pos.height + 4, left: pos.left })
 setSelectionMenuVisible(true)
 })

 useEffect(() => {
 closeSelectionMenu()
 }, [editorInfo?.path])

 useEffect(() => {
 if (!reqEditor) return

 const mouseUpDisposable = reqEditor.onMouseUp((e) => {
 if (!e.event.leftButton) return
 requestAnimationFrame(() => updateSelectionMenuPosition(reqEditor))
 })
 const selectionDisposable = reqEditor.onDidChangeCursorSelection((e) => {
 const selectedText = reqEditor.getModel()?.getValueInRange(e.selection) || ''
 if (!selectedText) {
 closeSelectionMenu()
 } else if (selectionMenuVisibleRef.current) {
 updateSelectionMenuPosition(reqEditor)
 }
 })
 const scrollDisposable = reqEditor.onDidScrollChange(() => {
 if (selectionMenuVisibleRef.current) {
 updateSelectionMenuPosition(reqEditor)
 }
 })
 const blurDisposable = reqEditor.onDidBlurEditorWidget(closeSelectionMenu)

 return () => {
 mouseUpDisposable.dispose()
 selectionDisposable.dispose()
 scrollDisposable.dispose()
 blurDisposable.dispose()
 }
 }, [reqEditor, closeSelectionMenu, updateSelectionMenuPosition])

 const rightContextMenu: OtherMenuListProps = useCreation(() => {
 return {
 sendAIActions: {
 menu: [{ key: 'sendAI', label: t('RunnerTabs.sendAIActions') }],
 onRun: (editor: IMonacoEditor, key: string) => {
 if (key === 'sendAI') {
 onSendAIAction(editor)
 }
 },
 },
 }
 }, [i18nRefresh])

 return (<div className={styles['runner-tab-pane']}>
 {editorInfo &&!editorInfo.isPlainText &&!allowBinary? (<div className={styles['warning-editor']}>
 <Result
 status={'warning'}
 // title={"此文件是二进制文件或使用了不受支持的文本编码，所以无法在文本编辑器中显示。"}
 subTitle={t('RunnerTabs.binaryNotice')}
 extra={[<YakitButton size="max" type="primary" onClick={onOpenBinary}>
 {t('RunnerTabs.openAnyway')}
 </YakitButton>,
 ]}
 />
 </div>): (<>
 {isIRify() && editorInfo?.aiReport? (<div className={styles['mark-down-wrapper']}>
 <StreamMarkdown content={editorInfo?.code || ''} />
 </div>): (<div className={styles['runner-tab-pane-editor']}>
 <YakitEditor
 editorOperationRecord="YAK_RUNNNER_EDITOR_RECORF"
 editorDidMount={setReqEditorFun}
 // 因monaco版本兼容问题 如若type传入“javascript”等，则可能会抛出错误 进而影响dnd拖拽
 type={editorInfo?.language}
 value={editorInfo?.code || ''}
 setValue={setYakitEditorValue}
 highLightText={
 editorInfo?.highLightRange? Array.isArray(editorInfo.highLightRange)? editorInfo.highLightRange: [editorInfo.highLightRange]: undefined
 }
 highLightClass="hight-light-yak-runner-color"
 contextMenu={rightContextMenu}
 />
 {selectionMenuVisible && (<div
 className={styles['selection-menu-overlay']}
 style={{ top: selectionMenuPos.top, left: selectionMenuPos.left }}
 >
 <IrifyAiCodeAuditSelectionMenu
 close={closeSelectionMenu}
 onSend={() => {
 if (reqEditor) {
 onSendAIActionRef.current(reqEditor)
 }
 }}
 />
 </div>)}
 </div>)}
 </>)}
 </div>)
})

