 ipcRenderer.invoke('Codec', { Type: 'fuzz', Text:

// SM4-CBC 字典爆破 - 输出加密后的字典数组供 Fuzzer 替换\:
// SM4-CBC 字典 Brute Force - 输出加密后的字典数组供 Fuzzer 替换
decodeSm4 = func(param) {
 key = codec.DecodeHex("31323334353637383930313233343536")~ /* 16 字节密钥 */
