 /**
 * 解析 deleteSessions 目标 id。
 * - deleteAll：全部索引中的 session
 * - sessionIds 非空：用传入集合
 * - 否则必须带非空 source：这些 source 下全部（跨 route / page）
 * - 非法（空 id 且无 source 且非 deleteAll）：返回 null
 */
 private resolveDeleteSessionIds(params: DeleteSessionsParams): string[] | null {
 const { sessionIds, source, deleteAll } = params
 if (deleteAll) return [...this.sessionOwnerMap.keys()]
 if (sessionIds?.length) return [...sessionIds]
 if (source?.length) {
 const sourceSet = new Set(source)
 const ids: string[] = []
 for (const [sessionId, owner] of this.sessionOwnerMap) {
 if (sourceSet.has(owner.source)) ids.push(sessionId)
 }
 return ids
 }
 console.error('[ChatMultiSessionController] deleteSessions: invalid params', params)
 return null
 }

 /** 该 PageKey 下所有 source 的 session 并集 */
 private resolvePageSessionIds(route: YakitRouteType, pageId: string): string[] {
 const sourceMap = this.pageSessionMap.get(makePageKey(route, pageId))
 if (!sourceMap) return []
 const ids: string[] = []
 for (const sessionSet of sourceMap.values()) {
 for (const id of sessionSet) {
 ids.push(id)
 }
 }
 return ids
 }

 /**
 * 按 source + route 查询当前索引中的 sessionId 集合（跨该 route 下所有 pageId）
 */
 public getSessionIdsBySourceAndRoute(source: DeleteSessionsAISourceType, route: YakitRouteType): string[] {
 const ids: string[] = []
 for (const [sessionId, owner] of this.sessionOwnerMap) {
 if (owner.source === source && owner.route === route) {
 ids.push(sessionId)
 }
 }
 return ids
 }

 /** 从传入的 sessionId 集合中筛出 store.execute === true 的会话 */
 public filterExecutingSessionIds(sessionIds: string[]): string[] {
 return sessionIds.filter((sessionId) => this.getSessionExecute(sessionId))
 }

 /** 只读查询已登记会话或 pending（含失败待重试）的归属，不创建会话数据。 */
 public getSessionPageId(sessionId: string, route?: YakitRouteType): string | undefined {
 const owner = this.sessionOwnerMap.get(sessionId)
 if (owner) return!route || owner.route === route? owner.pageId: undefined
 for (const connection of this.connectionsByToken.values()) {
 if (!connection.registered &&
 connection.sessionId === sessionId &&
 (!route || connection.input.route === route)) {
 return connection.input.pageId
 }
 }
 return undefined
 }

 /**
 * 只读查询 session 是否在执行中；无内存池时返回 false，不会 ensureSession 造空池
 */
 public getSessionExecute(sessionId: string): boolean {
 return this.storePool.get(sessionId)?.getState().execute === true
 }

 /** 进行中会话并发上限：未登录 2、已登录 5 */
 public getMaxExecutingSessions(): number {
 return useStore.getState().userInfo.isLogin? ChatMultiSessionController.MAX_EXECUTING_SESSIONS_LOGGED_IN: ChatMultiSessionController.MAX_EXECUTING_SESSIONS_LOGGED_OUT
 }

 /** 会话是否正在执行（提问等待回复 / 任务进行中 / 带首问的建连中）；纯打开历史不算 */
 public isSessionWorking(sessionId: string): boolean {
 const store = this.storePool.get(sessionId)
 if (!store) return false
 const state = store.getState()
 if (!state.execute) return false
 return (state.currentChatStatus.status === AITaskStatus.inProgress ||
 state.pendingReply ||!!(state.initLoading && this.metaPool.get(sessionId)?.createChatQuestion))
 }

 /** 尚未就绪的新建首问也占用并发名额，绑定后由正式会话接管计数。 */
 private isPendingConnectionWorking(connection: SessionConnection): boolean {
 const { lifecycle, createChatQuestion } = connection.data.meta
 return!connection.registered && lifecycle.current &&!lifecycle.closing &&!!createChatQuestion
 }

 public getWorkingSessionCount(): number {
 let count = 0
 for (const id of this.readyChannels) {
 if (this.isSessionWorking(id)) count++
 }
 for (const connection of this.connectionsByToken.values()) {
 if (this.isPendingConnectionWorking(connection)) count++
 }
 return count
 }

 /** 该页是否还有进行中的会话（关页前用来决定要不要确认） */
 public hasWorkingSessionOnPage(route: YakitRouteType, pageId: string) {
 return (this.resolvePageSessionIds(route, pageId).some((sessionId) => this.isSessionWorking(sessionId)) ||
 [...this.connectionsByToken.values()].some((connection) =>
 connection.input.route === route &&
 connection.input.pageId === pageId &&
 this.isPendingConnectionWorking(connection),))
 }

 /** 本会话已在执行中可继续；否则按项目内正在执行的会话数判断。notify 为 true 时超限提示 */
 public canStartExecutingSession(sessionId?: string, notify = false): boolean {
 if (sessionId && this.isSessionWorking(sessionId)) return true
 const ok = this.getWorkingSessionCount() < this.getMaxExecutingSessions()
 if (!ok && notify) {
 const isLogin = useStore.getState().userInfo.isLogin
 if (isLogin) {
 yakitNotify('warning',
 tAgent('AIChatLoading.executingSessionsLimitLoggedIn', { count: this.getMaxExecutingSessions() }),)
 } else {
 yakitNotify('warning', {
 message: createElement('span',
 null,
 tAgent('AIChatLoading.executingSessionsLimitLoggedOutPrefix'),
 createElement('span',
 {
 style: { color: 'var(--Colors-Use-Main-Primary)', cursor: 'pointer' },
 onClick: (e: { stopPropagation?: () => void }) => {
 e.stopPropagation?.()
 emiter.emit('onOpenLogin', '')
 },
 },
 tAgent('AIChatLoading.executingSessionsLimitLogin'),),
 tAgent('AIChatLoading.executingSessionsLimitLoggedOutSuffix'),),
 })
 }
 }
 return ok
 }

 /**
 * 同 route 下换绑 pageId：更新 sessionOwnerMap.pageId，从旧 PageKey 摘除、写入新 PageKey
 * route / source 不变；newPageId 与旧相同或 session 已 dispose 则 no-op
 */
 public rebindSessionPageId(sessionId: string, newPageId: string) {
 const owner = this.sessionOwnerMap.get(sessionId)
 if (!owner || owner.pageId === newPageId) return

 this.removeFromPageSessionMap(owner, sessionId)
 owner.pageId = newPageId
 this.addToPageSessionMap(owner, sessionId)
 }
