interface CompileHistoryListProps {
 pageInfo: YakRunnerScanHistoryPageInfoProps
 clickItem: SSAProgram | undefined
 setClickItem: (item?: SSAProgram) => void
}

// 编译历史列表
const CompileHistoryList: React.FC<CompileHistoryListProps> = (props) => {
 const { pageInfo } = props
 const { t } = useI18nNamespaces(['yakRunner', 'yakitUi'])
 const [loading, setLoading] = useState<boolean>(false)
 const [hasMore, setHasMore] = useState<boolean>(false)
 const [isRefresh, setIsRefresh] = useState<boolean>(false)
 const [collapsedGroups, setCollapsedGroups] = useState<Set<string>>(new Set())
 const [checkedList, setCheckedList] = useState<number[]>([])
 const [clickItem, setClickItem] = useControllableValue<SSAProgram | undefined>(props, {
 defaultValue: undefined,
 valuePropName: 'clickItem',
 trigger: 'setClickItem',
 })
 const latestClickItemRef = useLatest(clickItem)
 const [query, setQuery] = useState<QuerySSAProgramRequest>({
 Pagination: {
 Page: 1,
 Limit: 20,
 OrderBy: 'created_at',
 Order: 'desc',
 },
 Filter: {},
 })
 const [response, setResponse] = useState<QuerySSAProgramResponse>({
 Pagination: genDefaultPagination(20),
 Data: [],
 Total: 0,
 })
 useEffect(() => {
 update(1)
 }, [pageInfo])

 const update = useMemoizedFn((page: number) => {
 setLoading(true)
 const paginationProps = {...query.Pagination,
 Page: page,
 Limit: 20,
 }
 const finalParams: QuerySSAProgramRequest = {
 Filter: {...query.Filter,
 ProjectIds: pageInfo.ProjectIds,
 },
 Pagination: paginationProps,
 }

 const isInit = page === 1
 apiQuerySSAPrograms(finalParams).then((res: QuerySSAProgramResponse) => {
 const resData = res?.Data || []
 if (resData.length > 0) {
 setQuery((prevQuery) => ({...prevQuery,
 Pagination: {...prevQuery.Pagination,
 Page: +res.Pagination.Page,
 },
 }))
 }
 const d = isInit? resData: (response?.Data || []).concat(resData)
 const displayItems = buildCompileHistoryDisplayList(d)
 if (displayItems.length > 0) {
 const selectedProgram = pageInfo.SelectedProgramName? displayItems.find((item) => item.program.Name === pageInfo.SelectedProgramName)?.program: undefined
 setClickItem(selectedProgram || displayItems[0].program)
 }
 const isMore = resData.length < res.Pagination.Limit || d.length === response.Total

 setHasMore(!isMore)
 setResponse({...res,
 Data: d,
 })
 if (isInit) {
 setIsRefresh((prevIsRefresh) =>!prevIsRefresh)
 }
 }).finally(() => {
 setLoading(false)
 }).catch(() => {})
 })

 const handleCheckboxChange = useMemoizedFn((e: CheckboxChangeEvent, id: number) => {
 const checked = e.target.checked
 setCheckedList((prevCheckedList) => {
 if (checked) {
 return [...prevCheckedList, id]
 } else {
 return prevCheckedList.filter((item) => item!== id)
 }
 })
 })

 // 多个删除
 const onRemoveMultiple = useMemoizedFn(() => {
 setLoading(true)
 let params: DeleteSSAProgramRequest = {
 Filter: {
 Ids: checkedList,
 },
 }
 if (checkedList.length === 0) {
 params = {
 DeleteAll: true,
 }
 }
 ipcRenderer.invoke('DeleteSSAPrograms', params).then(() => {
 update(1)
 setCheckedList([])
 success(t('YakitNotification.deleted'))
 }).catch((error) => {
 setLoading(false)
 failed(t('YakitNotification.deleteFailed', { error: String(error) }))
 })
