function scheduleNamespaceRefresh(ns: I18nNamespace) {
 pendingNs.add(ns)
 if (nsRefreshTimer) clearTimeout(nsRefreshTimer)
 nsRefreshTimer = setTimeout(() => {
 nsRefreshTimer = null
 const namespaces = Array.from(pendingNs)
 pendingNs.clear()
 namespaces.forEach((name) => {
