 */
function bumpLangVersion(lng: string) {
 if (!lng || lng === lastEmittedLang) return

 if (nsRefreshTimer) {
 clearTimeout(nsRefreshTimer)
 nsRefreshTimer = null
 }
 pendingNs.clear()

 lastEmittedLang = lng
 langVersion += 1
 emitRefresh()
}

