 const removeToggleHijack = (pName: string, pid?: number) => {
 setHijackTasks((prev) => {
 const exists = prev.some((t) => {
 if (pid) {
 return t.pid === pid
 }
 return t.pName === pName &&!t.pid
 })
 if (exists) {
 return prev.filter((t) => {
 if (pid) {
 return t.pid!== pid
 }
 return t.pName!== pName &&!t.pid
 })
 }
 // 如若没找到 则是由进程名劫持的多个pid 停止其多个任务
 else {
 return prev.filter((t) => {
 return pid?!(t.pids || []).includes(pid): t
 })
 }
 })
 }

