 f["Cyan"] = func() { f["__colors"] = append(f["__colors"], "Cyan") }
 f["Grey"] = func() { f["__colors"] = append(f["__colors"], "Grey") }
 return f
 }

 saved = []
 modify = func(f) { saved = append(saved, f) }
 drop = func() { log.error("should not drop") }

