 // 仅当存在响应方向的 chunk（SSE 等响应增量）时才算流式响应；
 // 请求分块（Direction=REQUEST）不应触发流式响应展示路径。
 const isStreamingResponse =!!loading && (fuzzerResponse?.RandomChunkedData || []).filter(isResponseChunkedData).length > 0

 const assembledResponsePackage = useCreation(() => {
 const header = fuzzerResponse?.ResponseRaw || new Uint8Array()
 // 仅拼接响应方向的 chunk（SSE 等响应增量）。请求分块（Direction=REQUEST，
 // 随机分块传输发送的请求 body）不能拼到响应里，否则会出现「开启分块传输后
 // 响应回显请求 body」的 bug。缺省 Direction（兼容旧后端）按响应处理。
 const chunks = (fuzzerResponse?.RandomChunkedData || []).filter(isResponseChunkedData)
 if (chunks.length === 0) return header

 const bodyParts = chunks.slice().sort((a, b) => (Number(a?.Index) || 0) - (Number(b?.Index) || 0)).map((c) => c?.Data || new Uint8Array()).filter((d) => d.length > 0)
 if (bodyParts.length === 0) return header

 const bodyLen = bodyParts.reduce((acc, cur) => acc + cur.length, 0)
 const body = new Uint8Array(bodyLen)
 let offset = 0
 bodyParts.forEach((p) => {
 body.set(p, offset)
 offset += p.length
 })

 const maxBodyBytes = 5 * 1024 * 1024
 const boundedBody = body.length > maxBodyBytes? body.subarray(body.length - maxBodyBytes): body

 const out = new Uint8Array(header.length + boundedBody.length)
 out.set(header, 0)
 out.set(boundedBody, header.length)
 return out
 }, [fuzzerResponse?.ResponseRaw,
 fuzzerResponse?.RandomChunkedData,
 fuzzerResponse?.BodyLength,
 fuzzerResponse?.DurationMs,
 ])

