 apiFetchGroupStatisticsMine().then((res) => {
 const list = (res?.data || []).filter((item) =>!excludeFilterName.includes(item.groupKey))
 setFilterList(list)
 })
 }
 if (type === 'local') {
 apiFetchGroupStatisticsLocal().then((res) => {
 const list = (res?.data || []).filter((item) =>!excludeFilterName.includes(item.groupKey))
 setFilterList(list)
 })
 }
 return () => {
 setFilterList([])
 }
 }, [refresh])

 const [form] = Form.useForm()
 useEffect(() => {
 onSetIsActive(defaultFilter)
 }, [defaultFilter])
 useEffect(() => {
 if (!visible) return
 form.setFieldsValue({...defaultFilter })
 }, [defaultFilter, visible])
 /**需求：详情的搜索会清除tag，插件组因为已经移出到外面，所以插件组不会被清除 */
 const onFinish = useMemoizedFn((value) => {
 for (const name of excludeFilterName) {
 if (has(value, name)) delete value[name]
 }
 onFilter({...value, plugin_group: defaultFilter.plugin_group })
 setVisible(false)
 onSetIsActive(value)
 })
 /**需求：详情的重置会清除tag，插件组因为已经移出到外面，所以插件组不会被清除 */
 const onReset = useMemoizedFn(() => {
 const value = {
 plugin_type: [],
 status: [],
 plugin_private: [],
 plugin_group: defaultFilter.plugin_group,
 }
 form.setFieldsValue({...value,
 })
 onFilter(value)
 setVisible(false)
 setIsActive(false)
 })
 /** 显示激活状态判断 */
 const onSetIsActive = useMemoizedFn((value: PluginFilterParams) => {
 const valueArr = (Object.keys(value) || []).filter((item) =>!excludeFilterName.includes(item))
 if (valueArr.length > 0) {
 let isActive = false
 valueArr.forEach((key) => {
 if (value[key] && value[key].length > 0) {
 if (fixFilterList.length > 0) {
 const groupData = fixFilterList.find((ele) => ele.groupKey === 'key') || { data: [] }
 const list = (value[key] || []).map((ele) => ele.value).sort().join(',')
 const defList = (groupData.data || []).map((ele) => ele.value).sort().join(',')
 if (list && list!== defList) {
 isActive = true
 }
 } else {
 isActive = true
 }
 }
 })
 setIsActive(isActive)
 }
 })
 return (<YakitPopover
 classNames={{ root: styles['filter-popover-btn'] }}
 placement="bottomLeft"
 trigger={['click']}
 open={visible}
 onOpenChange={(value) => {
 setVisible(value)
 if (!value) onFinish(form.getFieldsValue())
 }}
 content={
 <div className={styles['filter-popover-btn-wrapper']}>
 <Form form={form} layout="vertical" onFinish={onFinish}>
 {filterList.map((item) => {
 return (<Form.Item key={item.groupKey} name={item.groupKey} label={item.groupName}>
 <YakitSelect labelInValue mode="multiple" allowClear={true}>
 {item.data.map((el) => (<YakitSelect.Option key={el.value} value={el.value}>
 {el.label}
 </YakitSelect.Option>))}
 </YakitSelect>
 </Form.Item>)
 })}

 <div className={styles['form-btns']}>
 <YakitButton type="text" onClick={onReset}>
 {t('FuncTemplate.resetSearch')}
 </YakitButton>
 <YakitButton type="primary" htmlType="submit">
 {t('YakitInput.search')}
 </YakitButton>
 </div>
 </Form>
 </div>
 }
 >
 <YakitButton type="text2" icon={<FilterOutlined color="currentColor" />} isHover={visible} isActive={isActive} />
 </YakitPopover>)
})

