const getBoundaries = (arr: number[]) => {
 // 将数组按升序排序
 arr.sort((a, b) => a - b)

 // 数组长度
 const len = arr.length

 // 计算 5 等分的边界索引
 const boundaries: number[] = []
 for (let i = 1; i < 5; i++) {
 // 计算每个分类的分界线索引，注意使用 Math.floor 确保取整
 const boundaryIndex = Math.floor((i * len) / 5)
 boundaries.push(arr[boundaryIndex])
 }

 return boundaries
}
const findRegion = (num, boundaries) => {
 let alpha = 1
 let index = -1
 const length = boundaries.length
 // 遍历分界线，找到数字所在区域
 for (let i = 0; i < length; i++) {
 if (num <= boundaries[i]) {
 index = i + 1
 break
 }
 }
 if (index === -1) {
 index = 5
 }
 switch (index) {
 case 1:
 alpha = 0.2
 break
 case 2:
 alpha = 0.4
 break
 case 3:
 alpha = 0.6
 break
 case 4:
 alpha = 0.8
 break
 case 5:
 alpha = 1
 break
 default:
 break
 }
 return alpha
}
